        if (operation.isTerminal()) throw new OperationCancelledException();
        if (scan.keys().isEmpty()) {
            throw scan.clientKexUnsupported()
                    ? hostKeyScanUnsupportedKex(operation.ssh.host())
                    : hostKeyUnavailable(operation.ssh.host());
        }
        List<String> scanned = scan.keys();
